import math
    import random
    import time

    LANGUAGE_WRAPPER = 'In a math contest with {alpha} participants, the following parametric optimization problem is posed.\n\nLet x, y, z be positive real numbers satisfying xyz = {r}(x + y + z) and yz ≠ {r}. Determine the exact minimum value of\n\nF(x, y, z) = {a} x^2 + {b} (yz - {r})^2 + {c} / (y + z)^2.\n\nGive your final answer as a single exact number.'

    class _RNGShim:
def __init__(self, seed: int):
    import random as _random
    self._seed = int(seed)
    self._r = _random.Random(self._seed)

def random(self): return self._r.random()
def uniform(self, a, b): return self._r.uniform(a, b)
def randint(self, a, b): return self._r.randint(a, b)
def randrange(self, *args): return self._r.randrange(*args)
def choice(self, seq): return self._r.choice(seq)
def choices(self, population, weights=None, cum_weights=None, k: int = 1):
    return self._r.choices(population, weights=weights, cum_weights=cum_weights, k=k)
def sample(self, population, k: int): return self._r.sample(population, k)
def shuffle(self, x):
    self._r.shuffle(x)
    return x
def getrandbits(self, k: int): return self._r.getrandbits(k)

    def generator(rng):
# We construct parameters so that the minimum is an integer via an exact AM-GM setup,
# and so that equality is achievable by positive reals (feasibility check on y, z).
# Strategy: choose integers a0, b0, c0, r such that
#   a = a0^3, b = b0^3, c = c0^3 * r,
# then the minimum will be 3 * (a*b*c*r^2)^(1/3) = 3 * a0 * b0 * c0 * r, an integer.
# Additionally ensure feasibility: there exist y, z > 0 with (y+z)^2 >= 4(yz) and yz = r + sqrt(t),
# where t and u are the AM-GM equality variables. This reduces to a check s^2 >= 4(r + sqrt(t)).

def try_sample():
    r = rng.randint(2, 7)
    a0 = rng.randint(2, 5)
    b0 = rng.randint(2, 5)
    # Make c0 comparatively larger to help feasibility
    c0 = rng.randint(4, 9)
    a = a0**3
    b = b0**3
    c = (c0**3) * r
    # AM-GM equality quantities
    # After substitution x = r(y+z)/(yz - r), the objective becomes
    #   a r^2 (y+z)^2/(yz - r)^2 + b (yz - r)^2 + c/(y+z)^2.
    # Put u = 1/(y+z)^2, t = (yz - r)^2.
    # Equality AM-GM gives u = (a r^2 b)^(1/3) / c^(2/3), t = (c/b) u.
    # With our construction, these simplify to
    #   u = (a0*b0)/(c0^2), t = (a0*c0*r)/(b0^2).
    u = (a0 * b0) / float(c0**2)
    t = (a0 * c0 * r) / float(b0**2)
    if u <= 0 or t <= 0:
        return None
    s2 = 1.0 / u
    p = r + (t ** 0.5)
    # Feasibility requires s^2 >= 4p.
    if s2 + 1e-12 < 4.0 * p:
        return None
    # Also ensure non-triviality: coefficients not all similar and answer reasonably large.
    ans = 3 * a0 * b0 * c0 * r
    if ans < 48:
        return None
    # Avoid too-symmetric triviality
    if len({a, b, c}) < 3:
        return None
    alpha_story = rng.randint(40, 120)
    return {
        'alpha': alpha_story,
        'a': a,
        'b': b,
        'c': c,
        'r': r
    }

# Attempt random sampling multiple times
for _ in range(200):
    out = try_sample()
    if out is not None:
        return out

# Fallback deterministic construction to guarantee feasibility
r = 2
a0, b0, c0 = 2, 2, 10
a = a0**3
b = b0**3
c = (c0**3) * r
alpha_story = rng.randint(40, 120)
return {
    'alpha': alpha_story,
    'a': a,
    'b': b,
    'c': c,
    'r': r
}

