    return x

prod = a * b * c * (r**2)
k = iroot3(prod)
if k**3 != prod:
    return (False, None)  # We require perfect cube for exact integer answer
answer = 3 * k

# Attempt to construct equality-case (y, z) and then x to verify attainability
# From AM-GM equality conditions on u = 1/(y+z)^2 and t = (yz - r)^2:
# alpha = a r^2, beta = b, gamma = c.
