t = (gamma / beta) * u
if not (u > 0 and t > 0):
    return (False, None)
s2 = 1.0 / u
import math
p = r + math.sqrt(t)
D = s2 - 4.0 * p
if D < -1e-8:
    return (False, None)  # Not feasible
if D < 0:
    D = 0.0
s = math.sqrt(max(0.0, s2))
sqrtD = math.sqrt(D)
y = 0.5 * (s - sqrtD)
z = 0.5 * (s + sqrtD)
# Validate positivity and constraint
if not (y > 0 and z > 0):
    return (False, None)
denom = (y*z - r)
if abs(denom) < 1e-9:
    return (False, None)
x = r * (y + z) / denom
if not (x > 0):
    return (False, None)

# Check the constraint xyz = r(x+y+z)
lhs = x * y * z
rhs = r * (x + y + z)
if abs(lhs - rhs) > 1e-6 * max(1.0, abs(rhs)):
    return (False, None)

# Evaluate the objective and compare to the computed answer
F = a * x * x + b * (y*z - r) ** 2 + c / ((y + z) ** 2)
if not (abs(F - answer) <= 1e-6 * max(1.0, abs(answer))):
    return (False, None)

# Additional non-triviality checks
